const cats=[['idle','walk','run','jump','dodge','block','combo'],['charge','Blitz','Special','grab','throw','down','recovery']];function sheet(){const page=+$('page').value;audit.fillStyle='#142633';audit.fillRect(0,0,1400,1140);const heroes=['reina','nova','broxton','forest','niko','gunner'];heroes.forEach((h,row)=>{audit.fillStyle='#e7e5cb';audit.font='bold 14px monospace';audit.fillText(h.toUpperCase(),10,row*190+19);cats[page].forEach((cat,col)=>{const x=col*200+100,y=row*190+173;let f=N.actor(h,0,0);f.hp=f.maxHp;f.dir=1;f.act=null;f.inv=0;f.down=0;f.walk=0;f.grappleZ=0;f.broxPose179=null;if(cat==='walk'||cat==='run'){f.walk=1;f.running=cat==='run';f.walkPhase=f.runPhase=.35;}if(cat==='jump'){f.jump=.2;f.act={name:h==='broxton'?'broxSuperman':'airKick',t:.18,total:.5,hitAt:.2};}if(cat==='dodge')f.act={name:h==='niko'?'nikoDodge185':'dodge',t:.2,total:.38,shuffle189:h==='broxton'};if(cat==='block')f.blocking=true;if(cat==='combo')f.act={name:h==='broxton'?'broxCombo179':h==='niko'?'nikoCombo185':'punch',t:.12,total:.4,hitAt:.1,combo:2};if(cat==='charge')f.act={name:'chargeHold130',t:.5,total:3};if(cat==='Blitz')f.act={name:h==='broxton'?'broxRush179':h==='niko'?'nikoBlitz185':h==='forest'?'forestBlitz':'blitzKick',t:.5,total:1.1};if(cat==='Special')f.act={name:h==='broxton'?'broxSpin':h==='niko'?'nikoClear185':'spin',t:.22,total:.8};if(cat==='grab'){const v=N.actor('thug',50,0);f.hold={victim:v,rear:false};}if(cat==='throw')f.act={name:'throw',t:.3,total:.9,hitAt:.4,pair:null};if(cat==='down'||cat==='recovery'){f.down=cat==='down'?1:.08;f.downTotal=1.5;f.downAge=1.5-f.down;f.grounded114=true;}if(h==='nova'&&f.act){if(cat==='combo')f.act.name='combo';if(cat==='Blitz')f.act.name='novaBlitz';if(cat==='Special')f.act.name='novaClear';if(cat==='throw')f.act.name='novaDDT';if(cat==='charge')f.act.name='hypeFlex';}if(h==='niko'){const poses={dodge:[0,10],combo:[0,6],Blitz:[0,9],Special:[1,10],throw:[1,4]};if(poses[cat])f.nikoPose185={sheet:poses[cat][0],index:poses[cat][1]};}if(h==='forest'){const poses={combo:['motion',8],Blitz:['motion',9],Special:['motion',10],throw:['grapple',5],charge:['extra',1]};if(poses[cat])f.forestPose125={sheet:poses[cat][0],index:poses[cat][1]};f.gaitRun127=cat==='run';f.gaitPhase127=.35;}audit.strokeStyle='#506971';audit.beginPath();audit.moveTo(x-90,y);audit.lineTo(x+90,y);audit.stroke();audit.fillStyle='#a7c6cd';audit.font='12px monospace';audit.fillText(cat,x-80,row*190+35);audit.save();audit.translate(x,y);audit.scale(.88,.88);if(h==='gunner'){PolishedSprites.draw(audit,{type:'gunner125',state:cat==='run'?'run':cat==='walk'?'walk':cat==='jump'?'leap':cat==='block'?'guard':cat==='combo'||cat==='Special'?'bite':cat==='down'?'rest':'alert',phase:.3,dir:1,hp:1,ai126:cat==='recovery'?{state:'Recovering',stunUntil:0}:null},.4,1);}else{try{PolishedSprites.draw(audit,f,1,N.Forest125.scale(f));}catch(e){audit.fillStyle='#ffd15f';audit.fillText('Use live action',-60,-30);}}audit.restore();});});}
$('stage').onclick=stage;$('step').onclick=()=>{g.tick(1/60,{});draw()};$('ten').onclick=()=>{for(let i=0;i<10;i++)g.tick(1/60,{});draw()};$('play').onclick=()=>running=!running;$('page').onchange=sheet;$('saveSheet').onclick=()=>{const a=document.createElement('a');a.download='hero-consistency189-'+$('page').value+'.png';a.href=$('sheet').toDataURL();a.click()};let last=0;function loop(t){if(running&&t-last>=1000/(60*+$('speed').value)){g.tick(1/60,{});last=t;draw()}requestAnimationFrame(loop)}Promise.resolve(PolishedSprites.ready).then(()=>{stage();sheet();requestAnimationFrame(loop)});
